import{_ as t,o as i,c as e,a3 as s}from"./chunks/framework.CRbjHCyB.js";const k=JSON.parse('{"title":"Quick Start","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Quick Start | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/catter/guide/quick-start"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/catter/guide/quick-start"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/catter/guide/quick-start"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/catter/guide/quick-start"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/catter/guide/quick-start"}]]},"headers":[],"relativePath":"catter/guide/quick-start.md","filePath":"en/catter/guide/quick-start.md","lastUpdated":1788608469000}'),n={name:"catter/guide/quick-start.md"};function l(p,a,r,o,d,h){return i(),e("div",null,[...a[0]||(a[0]=[s(`<h1 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h1><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A C++ project with any build system (Make, Ninja, CMake, Meson, etc.)</li></ul><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Catter is distributed as prebuilt packages on <a href="https://github.com/clice-io/catter/releases" target="_blank" rel="noreferrer">GitHub Releases</a>. Download the archive for your platform, extract it, and add the directory containing the <code>catter</code> executable to your <code>PATH</code>.</p><p>Prebuilt packages are currently available for:</p><table tabindex="0"><thead><tr><th>Platform</th><th>Architecture</th></tr></thead><tbody><tr><td>Windows</td><td>x64</td></tr><tr><td>Linux</td><td>x64</td></tr><tr><td>macOS</td><td>arm64</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Catter is under active development; always use the latest package from the Releases page. If there is no prebuilt package for your platform, see <a href="./../dev/build">Building from Source</a>.</p></div><h2 id="generate-a-compilation-database" tabindex="-1">Generate a Compilation Database <a class="header-anchor" href="#generate-a-compilation-database" aria-label="Permalink to &quot;Generate a Compilation Database&quot;">​</a></h2><p>Run your build command through catter to capture all compiler invocations:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">catter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> script::cdb</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile_commands.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> make</span></span></code></pre></div><p>This produces a <code>compile_commands.json</code> file in the current directory, ready for use with any language server or static analysis tool.</p><h2 id="command-format" tabindex="-1">Command Format <a class="header-anchor" href="#command-format" aria-label="Permalink to &quot;Command Format&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>catter [options] &lt;script&gt; [script-args] -- &lt;build-command&gt;</span></span></code></pre></div><p>Breaking down the CDB example:</p><table tabindex="0"><thead><tr><th>Part</th><th>Meaning</th></tr></thead><tbody><tr><td><code>script::cdb</code></td><td>Use the built-in CDB generation script (<code>script::</code> prefix selects built-in scripts)</td></tr><tr><td><code>-o compile_commands.json</code></td><td>Script-specific option: output file path</td></tr><tr><td><code>--</code></td><td>Separator between catter/script arguments and the build command</td></tr><tr><td><code>make</code></td><td>The actual build command to intercept</td></tr></tbody></table><h2 id="more-examples" tabindex="-1">More Examples <a class="header-anchor" href="#more-examples" aria-label="Permalink to &quot;More Examples&quot;">​</a></h2><h3 id="command-tree-visualization" tabindex="-1">Command tree visualization <a class="header-anchor" href="#command-tree-visualization" aria-label="Permalink to &quot;Command tree visualization&quot;">​</a></h3><p>View the captured build command DAG as an ASCII tree:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">catter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> script::cmd-tree</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> make</span></span></code></pre></div><h3 id="using-with-cmake" tabindex="-1">Using with CMake <a class="header-anchor" href="#using-with-cmake" aria-label="Permalink to &quot;Using with CMake&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">catter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> script::cdb</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile_commands.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><h3 id="custom-scripts" tabindex="-1">Custom scripts <a class="header-anchor" href="#custom-scripts" aria-label="Permalink to &quot;Custom scripts&quot;">​</a></h3><p>Use your own JavaScript script instead of a built-in one:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">catter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./my-script.js</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><h2 id="ide-support-for-script-development" tabindex="-1">IDE Support for Script Development <a class="header-anchor" href="#ide-support-for-script-development" aria-label="Permalink to &quot;IDE Support for Script Development&quot;">​</a></h2><p>After building, <code>api/</code> is a complete npm package: <code>api/package.json</code>, <code>api/dist/</code> (runtime JS modules), and <code>api/types/</code> (TypeScript declarations). Build it from the repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npm-install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build-js</span></span></code></pre></div><p>Then add <code>api/</code> to your script project as a local dependency (npm / pnpm / yarn):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --save-dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/catter/api</span></span></code></pre></div><p>Or declare it in <code>package.json</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;devDependencies&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;catter&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;file:../path/to/catter/api&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>This lets your script project import <code>catter/*</code> modules with full IDE autocompletion and type checking.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The <code>catter</code> npm package is not published to the registry yet; use the local dependency approach above until then. Once published, you can simply <code>npm install --save-dev catter</code>.</p></div>`,34)])])}const u=t(n,[["render",l]]);export{k as __pageData,u as default};
